<script setup lang="ts">
import { AlertCircle, CheckCircle2, Clock3, Headphones, MessageSquare, Plus, RefreshCw, Search, Send, Users, X } from '@lucide/vue';
const config = useRuntimeConfig();
const route = useRoute();
const { token, user } = useWorkspaceSession();
const { openContextMenu, copyText } = useContextMenu();
const dashboard = ref<any>(null);
const tickets = ref<any[]>([]);
const agents = ref<any[]>([]);
const selected = ref<any>(null);
const createOpen = ref(false);
const loading = ref(false);
const error = ref('');
const notice = ref('');
const search = ref('');
const statusFilter = ref('');
const sourceFilter = ref('');
const comment = ref('');
const internalComment = ref(false);
const section = computed(() => String(route.query.section || 'overview'));
const form = reactive({ subject:'', description:'', source:'EMPLOYEE', priority:'MEDIUM', affectedService:'Workspace' });
const statusLabels:Record<string,string> = { NEW:'Новая',OPEN:'В работе',WAITING_REQUESTER:'Ждём заявителя',WAITING_INTERNAL:'Внутреннее ожидание',RESOLVED:'Решена',CLOSED:'Закрыта' };
const priorityLabels:Record<string,string> = { LOW:'Низкий',MEDIUM:'Обычный',HIGH:'Высокий',CRITICAL:'Критический' };
const sourceLabels:Record<string,string> = { EMPLOYEE:'Сотрудник',B2C:'Клиент B2C',B2B:'Клиент B2B',SYSTEM:'Система' };
const filtered = computed(() => tickets.value.filter(ticket => (!statusFilter.value || ticket.status === statusFilter.value) && (!sourceFilter.value || ticket.source === sourceFilter.value) && (!search.value || `${ticket.number} ${ticket.subject} ${ticket.requesterEmail || ''}`.toLowerCase().includes(search.value.toLowerCase()))));
const queues = computed(() => Array.from(new Set(tickets.value.map(ticket => ticket.queue || 'Первая линия'))).map(queue => ({ name:queue, total:tickets.value.filter(ticket => (ticket.queue || 'Первая линия') === queue).length, open:tickets.value.filter(ticket => (ticket.queue || 'Первая линия') === queue && !['RESOLVED','CLOSED'].includes(ticket.status)).length })));
const slaState = (ticket:any) => ticket.resolutionDueAt && new Date(ticket.resolutionDueAt) < new Date() && !['RESOLVED','CLOSED'].includes(ticket.status) ? 'Просрочена' : 'В срок';
function requester(ticket:any) { return [ticket.requesterUser?.firstName,ticket.requesterUser?.lastName].filter(Boolean).join(' ') || ticket.requesterName || ticket.requesterEmail || sourceLabels[ticket.source]; }
async function load() { loading.value = true; error.value = ''; try { const headers={Authorization:`Bearer ${token.value}`}; [dashboard.value,tickets.value,agents.value]=await Promise.all([$fetch('/helpdesk/dashboard',{baseURL:config.public.apiBase,headers}),$fetch<any[]>('/helpdesk/tickets',{baseURL:config.public.apiBase,headers}),$fetch<any[]>('/helpdesk/agents',{baseURL:config.public.apiBase,headers})]); if(selected.value) selected.value=tickets.value.find(ticket=>ticket.id===selected.value.id)||null; } catch(e:any){error.value=e?.data?.message||'Не удалось загрузить Helpdesk';} finally{loading.value=false;} }
async function createTicket(){try{await $fetch('/helpdesk/tickets',{baseURL:config.public.apiBase,method:'POST',headers:{Authorization:`Bearer ${token.value}`},body:form});Object.assign(form,{subject:'',description:'',source:'EMPLOYEE',priority:'MEDIUM',affectedService:'Workspace'});createOpen.value=false;notice.value='Заявка создана';await load();setTimeout(()=>notice.value='',2200);}catch(e:any){error.value=e?.data?.message||'Не удалось создать заявку';}}
async function updateTicket(ticket:any, field:string, value:string){await $fetch(`/helpdesk/tickets/${ticket.id}`,{baseURL:config.public.apiBase,method:'PATCH',headers:{Authorization:`Bearer ${token.value}`},body:{[field]:value}});ticket[field]=value;notice.value='Заявка обновлена';setTimeout(()=>notice.value='',1800);}
async function addComment(){if(!comment.value.trim()||!selected.value)return;await $fetch(`/helpdesk/tickets/${selected.value.id}/comments`,{baseURL:config.public.apiBase,method:'POST',headers:{Authorization:`Bearer ${token.value}`},body:{body:comment.value,isInternal:internalComment.value}});comment.value='';internalComment.value=false;await load();}
function ticketMenu(event:MouseEvent,ticket:any){openContextMenu(event,ticket.number,[{label:'Открыть заявку',icon:'open',action:()=>selected.value=ticket},{label:'Копировать номер',icon:'copy',action:()=>copyText(ticket.number,'Номер заявки скопирован')},...(!['OPEN','RESOLVED','CLOSED'].includes(ticket.status)?[{label:'Взять в работу',icon:'status' as const,separator:true,action:()=>updateTicket(ticket,'status','OPEN')}]:[]),...(!['RESOLVED','CLOSED'].includes(ticket.status)?[{label:'Отметить решённой',icon:'status' as const,action:()=>updateTicket(ticket,'status','RESOLVED')}]:[])],requester(ticket));}
onMounted(load);
</script>

<template><main class="helpdesk-page"><header class="hd-header"><div><p class="eyebrow">IT HELPDESK / ЕДИНАЯ ПОДДЕРЖКА</p><h1>{{ section === 'tickets' ? 'Все заявки' : section === 'queues' ? 'Очереди поддержки' : section === 'knowledge' ? 'База знаний' : 'Центр поддержки' }}</h1><span>Сотрудники, B2C и B2B · единая очередь обращений</span></div><div><button class="outline" @click="load"><RefreshCw :size="16" :class="{spin:loading}" /> Обновить</button><button class="primary" @click="createOpen=true"><Plus :size="16" /> Новая заявка</button></div></header><WorkspaceLoading v-if="!dashboard && loading" label="Загружаем обращения" /><div v-else-if="error && !dashboard" class="state-error"><AlertCircle :size="22" /><span>{{ error }}</span><button @click="load">Повторить</button></div><div v-else class="hd-body">
  <template v-if="section === 'overview'"><section class="hd-kpis"><article><span>Новые</span><strong class="coral">{{ dashboard?.new || 0 }}</strong><small>ещё не распределены</small></article><article><span>В работе</span><strong>{{ dashboard?.inWork || 0 }}</strong><small>есть исполнитель</small></article><article><span>Ожидают</span><strong>{{ dashboard?.waiting || 0 }}</strong><small>ответа или действия</small></article><article><span>Просрочены</span><strong :class="{'red':dashboard?.overdue}">{{ dashboard?.overdue || 0 }}</strong><small>нарушен SLA</small></article></section><section class="hd-grid"><article class="panel"><div class="panel-head"><div><p class="eyebrow">ОПЕРАЦИОННАЯ ОЧЕРЕДЬ</p><h2>Требуют внимания</h2></div><NuxtLink to="/helpdesk?section=tickets">Все заявки</NuxtLink></div><div v-for="ticket in tickets.filter(t=>!['RESOLVED','CLOSED'].includes(t.status)).slice(0,6)" :key="ticket.id" class="ticket-compact" @click="selected=ticket" @contextmenu.prevent="ticketMenu($event,ticket)"><i :class="`priority-${ticket.priority.toLowerCase()}`"></i><span><strong>{{ ticket.subject }}</strong><small>{{ ticket.number }} · {{ requester(ticket) }}</small></span><b :class="{'overdue':slaState(ticket)==='Просрочена'}">{{ slaState(ticket) }}</b></div><p v-if="!tickets.length" class="empty">Обращений пока нет</p></article><article class="panel"><div class="panel-head"><div><p class="eyebrow">ИСТОЧНИКИ</p><h2>Откуда обращаются</h2></div></div><div v-for="source in ['EMPLOYEE','B2C','B2B','SYSTEM']" :key="source" class="source-row"><span>{{ sourceLabels[source] }}</span><b>{{ tickets.filter(ticket=>ticket.source===source).length }}</b><i><em :style="{width:`${tickets.length ? tickets.filter(ticket=>ticket.source===source).length/tickets.length*100 : 0}%`}"></em></i></div></article></section></template>
  <template v-else-if="section === 'tickets'"><section class="panel ticket-panel"><div class="filters"><label><Search :size="16" /><input v-model="search" placeholder="Номер, тема или заявитель" /></label><select v-model="statusFilter"><option value="">Все статусы</option><option v-for="(label,id) in statusLabels" :key="id" :value="id">{{ label }}</option></select><select v-model="sourceFilter"><option value="">Все источники</option><option v-for="(label,id) in sourceLabels" :key="id" :value="id">{{ label }}</option></select><button v-if="search||statusFilter||sourceFilter" @click="search='';statusFilter='';sourceFilter=''">Сбросить</button></div><div class="ticket-table"><div class="ticket-row head"><span>Заявка</span><span>Заявитель</span><span>Источник</span><span>Приоритет</span><span>Статус</span><span>SLA</span></div><div v-for="ticket in filtered" :key="ticket.id" class="ticket-row" @click="selected=ticket" @contextmenu.prevent="ticketMenu($event,ticket)"><div><strong>{{ ticket.subject }}</strong><small>{{ ticket.number }} · {{ new Date(ticket.createdAt).toLocaleString('ru-RU') }}</small></div><span>{{ requester(ticket) }}</span><span>{{ sourceLabels[ticket.source] }}</span><span :class="`text-${ticket.priority.toLowerCase()}`">{{ priorityLabels[ticket.priority] }}</span><span>{{ statusLabels[ticket.status] }}</span><span :class="{'red':slaState(ticket)==='Просрочена'}">{{ slaState(ticket) }}</span></div><p v-if="!filtered.length" class="empty">По заданным условиям заявок нет</p></div></section></template>
  <template v-else-if="section === 'queues'"><section class="queue-grid"><article v-for="queue in queues" :key="queue.name"><div><Users :size="19" /><span>{{ queue.name }}</span></div><strong>{{ queue.open }}</strong><small>в работе · всего {{ queue.total }}</small><button @click="navigateTo('/helpdesk?section=tickets')">Открыть очередь</button></article><article v-if="!queues.length" class="empty-card">Очереди появятся после первой заявки</article></section></template>
  <template v-else><section class="knowledge"><div><p class="eyebrow">САМООБСЛУЖИВАНИЕ</p><h2>База знаний SARKISIAN</h2><p>Инструкции будут подсказываться заявителю до отправки обращения и использоваться IT-командой в готовых ответах.</p></div><div class="knowledge-grid"><article><Headphones :size="20" /><h3>Рабочие системы</h3><p>Вход, права доступа и работа внутренних кабинетов.</p><span>Материалы готовятся</span></article><article><MessageSquare :size="20" /><h3>Клиентский сервис</h3><p>Ответы по заказам, оплате, доставке и возвратам.</p><span>Материалы готовятся</span></article><article><CheckCircle2 :size="20" /><h3>1С и интеграции</h3><p>Синхронизация товаров, остатков и каналов продаж.</p><span>Материалы готовятся</span></article></div></section></template>
</div>
<aside v-if="createOpen" class="backdrop" @click.self="createOpen=false"><form class="drawer create" @submit.prevent="createTicket"><header><div><p class="eyebrow">НОВОЕ ОБРАЩЕНИЕ</p><h2>Создать заявку</h2></div><button type="button" @click="createOpen=false"><X :size="18" /></button></header><div class="drawer-scroll"><label>Тема<input v-model="form.subject" required placeholder="Кратко опишите проблему" /></label><label>Подробное описание<textarea v-model="form.description" rows="7" required placeholder="Что произошло и какой результат ожидался" /></label><div class="two"><label>Источник<select v-model="form.source"><option v-for="(label,id) in sourceLabels" :key="id" :value="id">{{ label }}</option></select></label><label>Приоритет<select v-model="form.priority"><option v-for="(label,id) in priorityLabels" :key="id" :value="id">{{ label }}</option></select></label></div><label>Затронутый сервис<input v-model="form.affectedService" placeholder="Например, 1С или личный кабинет" /></label><div class="sla-note"><Clock3 :size="17" /><span><strong>SLA будет рассчитан автоматически</strong><small>По источнику, приоритету и рабочему календарю поддержки.</small></span></div></div><footer><button type="button" @click="createOpen=false">Отмена</button><button class="primary">Создать заявку</button></footer></form></aside>
<aside v-if="selected" class="backdrop" @click.self="selected=null"><section class="drawer ticket-detail"><header><div><p class="eyebrow">{{ selected.number }}</p><h2>{{ selected.subject }}</h2><span>{{ sourceLabels[selected.source] }} · {{ requester(selected) }}</span></div><button @click="selected=null"><X :size="18" /></button></header><div class="drawer-scroll"><div class="control-grid"><label>Статус<select :value="selected.status" @change="updateTicket(selected,'status',($event.target as HTMLSelectElement).value)"><option v-for="(label,id) in statusLabels" :key="id" :value="id">{{ label }}</option></select></label><label>Приоритет<select :value="selected.priority" @change="updateTicket(selected,'priority',($event.target as HTMLSelectElement).value)"><option v-for="(label,id) in priorityLabels" :key="id" :value="id">{{ label }}</option></select></label><label>Исполнитель<select :value="selected.assignedToId||''" @change="updateTicket(selected,'assignedToId',($event.target as HTMLSelectElement).value)"><option value="">Не назначен</option><option v-for="agent in agents" :key="agent.id" :value="agent.id">{{ [agent.firstName,agent.lastName].filter(Boolean).join(' ')||agent.email }}</option></select></label><label>Очередь<input :value="selected.queue" @change="updateTicket(selected,'queue',($event.target as HTMLInputElement).value)" /></label></div><section class="request-text"><h3>Описание</h3><p>{{ selected.description }}</p></section><section class="comments"><h3>Обсуждение</h3><div v-for="item in selected.comments" :key="item.id" :class="['comment',{internal:item.isInternal}]"><div><strong>{{ [item.author?.firstName,item.author?.lastName].filter(Boolean).join(' ')||item.author?.email||'Заявитель' }}</strong><span v-if="item.isInternal">Внутренний комментарий</span><small>{{ new Date(item.createdAt).toLocaleString('ru-RU') }}</small></div><p>{{ item.body }}</p></div><p v-if="!selected.comments?.length" class="empty">Комментариев пока нет</p></section></div><footer class="reply"><textarea v-model="comment" rows="2" placeholder="Написать ответ"></textarea><label><input v-model="internalComment" type="checkbox" /> Только для сотрудников</label><button class="send" :disabled="!comment.trim()" @click="addComment"><Send :size="16" /></button></footer></section></aside><div v-if="notice" class="toast">{{ notice }}</div></main></template>

<style scoped>
.helpdesk-page{min-height:100vh;background:var(--sb-bg);color:#202124;font-family:var(--sb-font)}.hd-header{min-height:112px;padding:23px 5%;box-sizing:border-box;background:#fff;border-bottom:1px solid var(--sb-line);display:flex;align-items:center;justify-content:space-between}.eyebrow{margin:0 0 8px;color:var(--sb-coral);font-size:9px;font-weight:600;letter-spacing:.16em}.hd-header h1{font-size:29px;margin:0 0 7px}.hd-header>div:first-child>span{font-size:10px;color:var(--sb-muted)}.hd-header>div:last-child{display:flex;gap:8px}.outline,.primary,.state-error button{height:40px;padding:0 14px;border:1px solid var(--sb-line);background:#fff;display:flex;align-items:center;gap:7px;font-size:11px}.primary{background:#1d1e22;color:#fff;border-color:#1d1e22}.spin{animation:spin 1s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}.hd-body{max-width:1220px;margin:auto;padding:28px 5% 70px}.hd-kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:13px}.hd-kpis article{background:#fff;border:1px solid var(--sb-line);padding:21px;display:grid;gap:8px}.hd-kpis span,.hd-kpis small{font-size:10px;color:var(--sb-muted)}.hd-kpis strong{font-size:28px;font-weight:500}.coral{color:var(--sb-coral)}.red{color:#c44e3e!important}.hd-grid{display:grid;grid-template-columns:1.2fr .8fr;gap:13px;margin-top:13px}.panel{background:#fff;border:1px solid var(--sb-line);padding:24px}.panel-head{display:flex;justify-content:space-between;margin-bottom:17px}.panel-head h2,.knowledge h2{margin:0;font-size:19px}.panel-head a{font-size:10px;color:var(--sb-coral);text-decoration:none}.ticket-compact{min-height:57px;display:grid;grid-template-columns:7px 1fr auto;align-items:center;gap:11px;border-bottom:1px solid #eff0f2;cursor:pointer}.ticket-compact>i{width:7px;height:7px;border-radius:50%;background:#a1a5ac}.ticket-compact>i.priority-critical{background:#c44939}.ticket-compact>i.priority-high{background:#e28d3f}.ticket-compact span{display:grid;gap:4px}.ticket-compact strong{font-size:10px}.ticket-compact small{font-size:8px;color:var(--sb-muted)}.ticket-compact>b{font-size:9px;color:#5a8d72;font-weight:500}.ticket-compact>b.overdue{color:#c44e3e}.source-row{display:grid;grid-template-columns:1fr auto;gap:8px;min-height:51px;align-content:center;border-bottom:1px solid #eff0f2}.source-row span,.source-row b{font-size:10px}.source-row i{grid-column:1/-1;height:3px;background:#f0f1f3}.source-row em{height:100%;display:block;background:#e78b7b}.ticket-panel{padding:0}.filters{padding:18px 22px;display:flex;gap:8px;border-bottom:1px solid #eff0f2}.filters label{height:36px;flex:1;display:flex;align-items:center;gap:8px;border:1px solid var(--sb-line);padding:0 10px;color:var(--sb-muted)}.filters input{border:0;outline:0;width:100%;font-size:11px}.filters select{height:36px;border:1px solid var(--sb-line);background:#fff;padding:0 10px;font-size:10px}.filters>button{border:0;background:none;color:var(--sb-coral);font-size:10px}.ticket-table{overflow:auto}.ticket-row{min-width:920px;min-height:54px;padding:0 22px;display:grid;grid-template-columns:2fr 1.2fr .8fr .8fr 1fr .7fr;gap:12px;align-items:center;border-bottom:1px solid #eff0f2;font-size:10px;cursor:pointer}.ticket-row:hover:not(.head){background:#fafafa}.ticket-row.head{min-height:42px;color:var(--sb-muted);text-transform:uppercase;font-size:8px}.ticket-row>div{display:grid;gap:4px}.ticket-row small{color:var(--sb-muted);font-size:8px}.text-critical{color:#c44939}.text-high{color:#c87b34}.queue-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.queue-grid article{background:#fff;border:1px solid var(--sb-line);padding:22px;display:grid;gap:9px}.queue-grid article>div{display:flex;align-items:center;gap:8px;color:var(--sb-coral);font-size:11px}.queue-grid strong{font-size:31px;font-weight:500}.queue-grid small{font-size:9px;color:var(--sb-muted)}.queue-grid button{height:36px;margin-top:6px;border:1px solid var(--sb-line);background:#fff;font-size:10px}.knowledge>div:first-child{background:#1d1e22;color:#fff;padding:28px}.knowledge>div:first-child>p:last-child{max-width:700px;color:#b8bbc0;font-size:11px;line-height:1.7}.knowledge-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin-top:13px}.knowledge-grid article{background:#fff;border:1px solid var(--sb-line);padding:24px}.knowledge-grid svg{color:var(--sb-coral)}.knowledge-grid h3{font-size:14px;margin:15px 0 8px}.knowledge-grid p{font-size:10px;line-height:1.6;color:var(--sb-muted)}.knowledge-grid span{font-size:8px;color:#aa7c72;text-transform:uppercase;letter-spacing:.1em}.backdrop{position:fixed;inset:0;z-index:600;background:#10111455}.drawer{position:absolute;right:0;top:0;bottom:0;width:min(590px,94vw);background:#fff;display:flex;flex-direction:column}.drawer>header{padding:26px 29px 20px;border-bottom:1px solid #e8e9ec;display:flex;justify-content:space-between}.drawer>header h2{font-size:23px;margin:0 0 5px}.drawer>header span{font-size:9px;color:var(--sb-muted)}.drawer>header button{border:0;background:none}.drawer-scroll{padding:23px 29px;overflow:auto;flex:1}.drawer-scroll>label,.control-grid label{display:grid;gap:7px;margin-bottom:15px;color:#74777f;font-size:10px}.drawer input,.drawer textarea,.drawer select{width:100%;height:40px;box-sizing:border-box;border:1px solid var(--sb-line);padding:0 10px;font:11px var(--sb-font)}.drawer textarea{height:auto;padding:10px;resize:vertical}.two,.control-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.sla-note{display:flex;gap:10px;padding:13px;background:#f4f6f8;color:#65707b}.sla-note span{display:grid;gap:4px}.sla-note strong{font-size:10px}.sla-note small{font-size:8px}.drawer>footer{padding:17px 29px;border-top:1px solid #e8e9ec;display:flex;justify-content:flex-end;gap:8px}.drawer>footer button{height:38px;padding:0 14px;border:0;background:#fff;font-size:10px}.drawer>footer button.primary{background:#1d1e22;color:#fff}.request-text,.comments{border-top:1px solid #ececef;padding:18px 0}.request-text h3,.comments h3{font-size:12px;margin:0 0 10px}.request-text p{font-size:11px;line-height:1.7;color:#555960}.comment{padding:12px;background:#f5f6f7;margin-bottom:8px}.comment.internal{background:#fff4e9}.comment>div{display:flex;gap:8px;align-items:center}.comment strong{font-size:9px}.comment span{padding:3px 5px;background:#e9cba9;font-size:7px}.comment small{margin-left:auto;font-size:7px;color:var(--sb-muted)}.comment p{font-size:10px;line-height:1.6;margin:8px 0 0}.reply{display:grid!important;grid-template-columns:1fr auto!important;justify-content:stretch!important}.reply textarea{grid-column:1/-1}.reply label{font-size:9px;color:var(--sb-muted)}.reply label input{width:auto;height:auto}.reply .send{width:38px;padding:0;display:grid;place-items:center;background:#1d1e22;color:#fff}.toast{position:fixed;right:22px;bottom:22px;background:#1d1e22;color:#fff;padding:12px 16px;font-size:10px;z-index:800}.empty{text-align:center;padding:30px;color:var(--sb-muted);font-size:10px}.state-error{min-height:60vh;display:grid;place-content:center;justify-items:center;gap:12px;color:#a65346;font:11px var(--sb-font)}@media(max-width:900px){.hd-kpis{grid-template-columns:repeat(2,1fr)}.hd-grid,.knowledge-grid{grid-template-columns:1fr}.queue-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.hd-header{align-items:flex-start;flex-direction:column;gap:15px}.hd-body{padding:20px}.filters{flex-wrap:wrap}.filters label{flex-basis:100%}.queue-grid{grid-template-columns:1fr}.two,.control-grid{grid-template-columns:1fr}}
</style>
